    #[tokio::test]
    async fn discard_thread_drops_unmaterialized_live_writer() {
        let home = TempDir::new().expect("temp dir");
        let store = LocalThreadStore::new(test_config(home.path()), /*state_db*/ None);
        for history_mode in [ThreadHistoryMode::Legacy, ThreadHistoryMode::Paginated] {
            let thread_id = ThreadId::default();
            let mut params = create_thread_params(thread_id);
            params.history_mode = history_mode;

            store
                .create_thread(params)
                .await
                .expect("create live thread");
            let rollout_path = store
                .live_rollout_path(thread_id)
                .await
                .expect("load rollout path");
            {
                let recorder = store
                    .live_recorders
                    .lock()
                    .await
                    .get(&thread_id)
                    .expect("live recorder")
                    .recorder
                    .clone();
                recorder
                    .record_canonical_items(&[user_message_item("deferred item to discard")])
                    .await
                    .expect("queue deferred item without materializing it");
            }
            assert!(!rollout_path.exists());

            let lock_path = home
                .path()
                .join("thread-writer-locks")
                .join(format!("{thread_id}.lock"));
            assert!(lock_path.exists());
            store
                .discard_thread(thread_id)
                .await
                .expect("discard live thread");

            assert!(!rollout_path.exists());
            assert!(!lock_path.exists());
            let err = store
                .append_items(AppendThreadItemsParams {
                    thread_id,
                    items: vec![user_message_item("write after discard")],
                })
                .await
                .expect_err("discard should remove the live thread writer");
